 item={'physical_sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'catalog_states':[x['state'] for x in records],'catalog_revisions':[x['catalog_revision'] for x in records]}
 try:
  fd=os.open(r/'mount-dfs'/name,os.O_RDONLY)
